sub allocate_surplus {
    my ($inventory, $facilities, $urgency) = @_;
    my @sorted_facilities = sort {
        $urgency->{$b} <=> $urgency->{$a}
    } keys %$facilities;
    foreach my $facility (@sorted_facilities) {
        my $capacity = $facilities->{$facility};
        my $allocation = $inventory > $capacity ? $capacity : $inventory;
