func analyzeMicrobiome(reads []string, threshold float64) map[string]int {
    taxaCounts := make(map[string]int)
    for _, read := range reads {
        taxa := identifyTaxa(read)
        if taxa != "" {
            taxaCounts[taxa]++
        }
    }
    dominantTaxa := make(map[string]int)
    totalReads := len(reads)
    for taxa, count := range taxaCounts {
