interface NoiseSource {
  frequency: number;
  powerLevel: number;
  position: [number, number];
}
function calculateSoundPressure(sources: NoiseSource[], distance: number): number {
  let totalPressure = 0;
  for (const source of sources) {
    const attenuation = 20 * Math.log10(distance) + 11;
    const pressure = source.powerLevel - attenuation;
    totalPressure += Math.pow(10, pressure / 10);
