def schedule_maintenance(current_moisture, target_moisture, grass_type):
    if current_moisture < target_moisture * 0.8:
        return "irrigate_field"
    elif current_moisture > target_moisture * 1.2:
        return "aerate_and_drain"
    elif grass_type == "perennial_ryegrass":
        return "light_fertilization"
    else:
        return "monitor_only"
